{
  "book_code": "TADAM",
  "verses": [
    {
      "chapter": 47,
      "verse": 1,
      "text_ar": "مبارك أنت أيها الرب، لأنك رحمت خليقتك."
    },
    {
      "chapter": 48,
      "verse": 1,
      "text_ar": "حينئذ رأى شيث يد الله ممدودة وهي تمسك آدم، فسلمه إلى"
    },
    {
      "chapter": 48,
      "verse": 2,
      "text_ar": "ميخائيل قائلًا: «ليكن في عهدتك إلى يوم الدينونة في العقاب، وإلى السنوات الأخيرة عندما أحول حزنه إلى فرح."
    },
    {
      "chapter": 48,
      "verse": 3,
      "text_ar": "حينئذ يجلس على عرش ذاك الذي كان غاصبه»."
    },
    {
      "chapter": 48,
      "verse": 4,
      "text_ar": "وقال الرب أيضًا للملاكين ميخائيل وأوريئيل: «إئتيا بثلاثة ثياب كتانية من البسوس وافرشاها على آدم وثياب كتانية أخرى على هابيل ابنه وادفنا آدم وهابيل ابنه»."
    }
  ]
}
